<?php
/*
 * AAT Business Club: lists every photo in members/photos/ (including sub-folders).
 * The club page reads this list, so uploading a photo is enough for it to appear.
 *
 * Name: taken from the file name (Mahmoud-Alauwais.jpg -> Mahmoud Alauwais).
 * Extra details (optional): members/data.json, keyed by the file path, e.g.
 *   { "2023/04/Mahmoud-Alauwais.jpg": { "name": "...", "company": "...", "country": "...", "bio": "..." } }
 * members/hidden.json lists repeated photos to skip (a JSON array of paths inside photos/).
 * Do not edit this file unless you know PHP.
 */
header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: public, max-age=300');
header('X-Content-Type-Options: nosniff');

// the scan of ~2,900 photos is kept for 10 minutes (and redone at once when hidden.json or data.json change),
// so many visitors at the same time do not make the server read the folder again and again
$cache = __DIR__ . '/list-cache.json';
if (is_file($cache)) {
    $age = time() - filemtime($cache);
    $newer = false;
    foreach (['hidden.json', 'data.json'] as $f) { if (is_file(__DIR__ . '/' . $f) && filemtime(__DIR__ . '/' . $f) > filemtime($cache)) { $newer = true; } }
    if ($age < 600 && !$newer) { readfile($cache); exit; }
}

$base = __DIR__ . '/photos';
$extra = [];
// repeated photos (same person, same picture) listed in hidden.json are skipped; the files stay on the server
$hidden = [];
if (is_file(__DIR__ . '/hidden.json')) {
    $list = json_decode(file_get_contents(__DIR__ . '/hidden.json'), true);
    if (is_array($list)) { $hidden = array_flip($list); }
}
if (is_file(__DIR__ . '/data.json')) {
    $parsed = json_decode(file_get_contents(__DIR__ . '/data.json'), true);
    if (is_array($parsed)) { $extra = $parsed; }
}

function clean_name($file) {
    $s = pathinfo($file, PATHINFO_FILENAME);
    $s = preg_replace('/^.*?\.{2,}\s*/u', '', $s);        // drop "Interview...-" style prefixes
    $s = preg_replace('/-(scaled|\d+x\d+)$/i', '', $s);   // drop WordPress size suffixes
    $s = str_replace(['-', '_', '.'], ' ', $s);
    $s = preg_replace('/(\p{L})\d+$/u', '$1', $s);        // drop a trailing copy number ("Salmi1")
    $s = preg_replace('/\s+\d+$/u', '', $s);             // drop a trailing " 1" copy number ("Sami El Khateeb 1")
    $s = preg_replace('/\s+/u', ' ', $s);
    $s = preg_replace('/\b(Dr|Prof)\s/u', '$1. ', $s);   // "Dr Nidal" -> "Dr. Nidal"
    return trim($s);
}

$members = [];
if (is_dir($base)) {
    $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($base, FilesystemIterator::SKIP_DOTS));
    foreach ($it as $file) {
        if (!$file->isFile()) { continue; }
        if (!in_array(strtolower($file->getExtension()), ['jpg', 'jpeg', 'png', 'webp'], true)) { continue; }
        $rel = str_replace('\\', '/', substr($file->getPathname(), strlen($base) + 1));
        $parts = array_map('rawurlencode', explode('/', $rel));
        $m = ['name' => clean_name(basename($rel)), 'photo' => 'members/photos/' . implode('/', $parts)];
        if (isset($hidden[$rel])) { continue; }
        if (isset($extra[$rel]) && is_array($extra[$rel])) { $m = array_merge($m, $extra[$rel]); }
        $members[] = $m;
    }
}
// the newest photos folder (e.g. photos/2026/10/) comes first: the club's new members are seen at once; then everyone by name
$latest = '';
foreach ($members as $m) { if (preg_match('#^members/photos/(\d{4}/\d{2})/#', $m['photo'], $g) && $g[1] > $latest) { $latest = $g[1]; } }
usort($members, function ($a, $b) use ($latest) {
    $na = $latest !== '' && strpos($a['photo'], 'members/photos/' . $latest . '/') === 0;
    $nb = $latest !== '' && strpos($b['photo'], 'members/photos/' . $latest . '/') === 0;
    if ($na !== $nb) { return $na ? -1 : 1; }
    return strnatcasecmp($a['name'], $b['name']);
});

$out = json_encode(['count' => count($members), 'members' => $members], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
@file_put_contents($cache, $out, LOCK_EX);
echo $out;
